-- C-104: hotel photos from the contact-sheet picks (scripts/photos/picks.json -> fetch.ts -> picked.json),
-- applied with scripts/catalog/photos-sql.ts. Licensed Wikimedia Commons images with credits; the web
-- app serves its own copies (apps/web/public/hotels), image_url feeds OG cards and emails.
alter table public.hotels add column if not exists image_source_url text;
update public.hotels h
set image_url = v.image_url, image_credit = v.image_credit, image_source_url = v.image_source_url
